import products from './products.json' with {type:'json'};

export async function listTools() {
  return [{
    name: 'inventory_search',
    description: 'Search products by name (case-insensitive).',
    inputSchema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'Search query string.' },
        limit: { type: 'integer', minimum: 1, maximum: 10, description: 'Maximum number of results (1-10).' }
      },
      required: ['query']
    }
  }];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error('Tool not found');
  }

  const query = args?.query;
  if (typeof query !== 'string' || query.trim() === '') {
    throw new Error('Invalid arguments: query must be a non-empty string');
  }

  let limit = args?.limit;
  if (limit !== undefined) {
    if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 1 || limit > 10) {
      throw new Error('Invalid arguments: limit must be an integer between 1 and 10');
    }
  }

  const q = query.toLowerCase();
  let results = products.filter(p => p.name.toLowerCase().includes(q));

  if (limit !== undefined) {
    results = results.slice(0, limit);
  }

  const text = results.length
    ? results.map(p => `${p.name} (${p.id})`).join('\n')
    : 'No products found';

  return { content: [{ type: 'text', text }] };
}

